#!/usr/bin/env bash
# Shared paths for the SG2002 reproducibility scripts.
set -euo pipefail

TESTS_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
REPRO_CONFIG=${REPRO_CONFIG:-$TESTS_ROOT/local-paths.conf}
[[ -f $REPRO_CONFIG ]] || {
  printf 'error: repository roots are not configured. Run configure.sh --help from the tests directory first.\n' >&2
  exit 2
}
# local-paths.conf is generated by configure.sh and is not committed.
# shellcheck source=/dev/null
source "$REPRO_CONFIG"
: "${AKARS_ROOT:?missing StarryOS application root}"
: "${TGOSKITS_ROOT:?missing StarryOS kernel root}"
: "${LINUX_AKARS_ROOT:?missing Linux application root}"
: "${LINUX_BASE_ROOT:?missing Linux baseline root}"
REPRO_OUTPUT_DIR=${REPRO_OUTPUT_DIR:-$TESTS_ROOT/artifacts}
MODEL_NAME=yolov8n_tennis_v2.cvimodel
MODEL_SHA256=60da9b28c5736624534cb625ee2b67bdb5081954e43e320e1d749421e5e4155b
TARGET_TRIPLE=riscv64gc-unknown-linux-musl

die() { printf 'error: %s\n' "$*" >&2; exit 1; }
need_file() { [[ -f $1 ]] || die "missing file: $1"; }
need_cmd() { command -v "$1" >/dev/null || die "missing command: $1"; }
check_model() {
  need_file "$1"
  local actual
  actual=$(sha256sum "$1")
  [[ ${actual%% *} == "$MODEL_SHA256" ]] || die "wrong 640x640 model hash: $1"
}
case_root() {
  case $1 in
    starry) printf '%s\n' "$AKARS_ROOT" ;;
    linux) printf '%s\n' "$LINUX_AKARS_ROOT" ;;
    *) die "OS must be starry or linux" ;;
  esac
}
case_board_dir() {
  case $1 in
    starry) printf '%s\n' /akars_tennis ;;
    linux) printf '%s\n' /root/akars_linux ;;
    *) die "OS must be starry or linux" ;;
  esac
}
case_model() {
  case $1 in
    starry) printf '%s\n' "$AKARS_ROOT/$MODEL_NAME" ;;
    linux) printf '%s\n' "$LINUX_AKARS_ROOT/$MODEL_NAME" ;;
    *) die "OS must be starry or linux" ;;
  esac
}
check_remote() {
  [[ $1 =~ ^[A-Za-z0-9_.-]+@[A-Za-z0-9_.-]+$ ]] || die "BOARD must look like root@board-ip-or-name"
}
